import fs from 'fs';
import os from 'os';
import path from 'path';

import { buildSite } from '../src/site';
import { TemplateEngine } from '../src/templates';

function tmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

