      expect(post).not.toContain('<main>');

      const about = fs.readFileSync(path.join(outputDir, 'about.html'), 'utf-8');
      expect(about).toContain('<main>');
    } finally {
      cleanup(path.join(outputDir, '..'));
    }
  });

