import fs from 'fs';
import http from 'http';
import path from 'path';
import { AddressInfo } from 'net';

import chokidar, { FSWatcher } from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';

import { buildSite } from './site';

export interface ServeOptions {
  content?: string;
  output?: string;
  templates?: string;
  port?: number;
  host?: string;
}

export interface ServeHandle {
  server: http.Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  port: number;
  host: string;
  address: string;
  outputDir: string;
  close: () => Promise<void>;
  rebuild: () => void;
}

export const LIVE_RELOAD_PATH = '/__ssg_livereload';

function liveReloadScript(): string {
  return `<script data-ssg-livereload>
(function () {
  var protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  var ws = new WebSocket(protocol + '//' + location.host + '${LIVE_RELOAD_PATH}');
  ws.addEventListener('message', function (event) {
    if (event.data === 'reload') {
      location.reload();
    }
  });
})();
</script>`;
}

export function injectLiveReloadScript(html: string): string {
  const script = liveReloadScript();
  if (html.includes('</body>')) {
    return html.replace('</body>', `${script}\n</body>`);
  }
  if (html.includes('</html>')) {
    return html.replace('</html>', `${script}\n</html>`);
  }
  return html + script;
}

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.mjs': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/markdown; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.eot': 'application/vnd.ms-fontobject',
  '.xml': 'application/xml; charset=utf-8',
};

export async function startServer(options: ServeOptions = {}): Promise<ServeHandle> {
  const contentDir = path.resolve(options.content ?? './content');
  const outputDir = path.resolve(options.output ?? './dist');
  const templatesDir = path.resolve(options.templates ?? './templates');
  const host = options.host ?? 'localhost';
  const requestedPort = options.port ?? 3000;

  const rebuild = (): void => {
    try {
      buildSite({ contentDir, outputDir, templatesDir });
    } catch (err) {
      console.error('Rebuild failed:', err);
    }
  };

  const server = http.createServer((req, res) => {
    const raw = req.url ?? '/';
    const queryIndex = raw.indexOf('?');
    const rawPath = queryIndex === -1 ? raw : raw.slice(0, queryIndex);
    let pathname = decodeURIComponent(rawPath);
    if (pathname === '/') {
      pathname = '/index.html';
    }
    const relative = pathname.replace(/^\/+/, '');
    const filePath = path.resolve(outputDir, relative);
    if (filePath !== outputDir && !filePath.startsWith(outputDir + path.sep)) {
      res.statusCode = 403;
      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
      res.end('Forbidden');
      return;
    }
    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.statusCode = 404;
        res.setHeader('Content-Type', 'text/plain; charset=utf-8');
        res.end('Not Found');
        return;
      }
      const ext = path.extname(filePath).toLowerCase();
      res.setHeader('Content-Type', MIME_TYPES[ext] ?? 'application/octet-stream');
      if (ext === '.html') {
        data = Buffer.from(injectLiveReloadScript(data.toString('utf-8')));
      }
      res.end(data);
    });
  });

  const wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });

  let closed = false;
  let rebuildTimer: NodeJS.Timeout | null = null;

  const broadcastReload = (): void => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  };

  const scheduleRebuild = (): void => {
    if (rebuildTimer) {
      clearTimeout(rebuildTimer);
    }
    rebuildTimer = setTimeout(() => {
      rebuildTimer = null;
      rebuild();
      broadcastReload();
    }, 150);
  };

  const watcher = chokidar.watch([contentDir, templatesDir], {
    ignoreInitial: true,
    ignored: (watchedPath: string) => {
      const resolved = path.resolve(watchedPath);
      return resolved === outputDir || resolved.startsWith(outputDir + path.sep);
    },
  });

  watcher.on('add', scheduleRebuild);
  watcher.on('change', scheduleRebuild);
  watcher.on('unlink', scheduleRebuild);
  watcher.on('addDir', scheduleRebuild);
  watcher.on('unlinkDir', scheduleRebuild);

  rebuild();

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(requestedPort, host, () => {
      resolve();
    });
  });

  const address = server.address() as AddressInfo;

  const close = (): Promise<void> => {
    return new Promise((resolve) => {
      if (closed) {
        resolve();
        return;
      }
      closed = true;
      if (rebuildTimer) {
        clearTimeout(rebuildTimer);
        rebuildTimer = null;
      }
      for (const client of wss.clients) {
        client.terminate();
      }
      watcher.close().then(() => {
        wss.close(() => {
          server.close(() => resolve());
        });
      });
    });
  };

  return {
    server,
    wss,
    watcher,
    port: address.port,
    host,
    address: `http://${host}:${address.port}`,
    outputDir,
    close,
    rebuild,
  };
}

#!/usr/bin/env node
import { buildSite, BuildResult } from './site';
import { startServer, ServeHandle } from './serve';

export interface CliOptions {
  command?: string;
  content?: string;
  output?: string;
  templates?: string;
  port?: number;
}

export function parseArgs(argv: string[]): CliOptions {
  const args = argv.slice(2);
  const options: CliOptions = {};

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      options.content = args[++i];
    } else if (arg === '--output' || arg === '-o') {
      options.output = args[++i];
    } else if (arg === '--templates' || arg === '-t') {
      options.templates = args[++i];
    } else if (arg === '--port' || arg === '-p') {
      const value = args[++i];
      if (value !== undefined) {
        options.port = Number(value);
      }
    } else if (arg.startsWith('--content=')) {
      options.content = arg.slice('--content='.length);
    } else if (arg.startsWith('--output=')) {
      options.output = arg.slice('--output='.length);
    } else if (arg.startsWith('--templates=')) {
      options.templates = arg.slice('--templates='.length);
    } else if (arg.startsWith('--port=')) {
      options.port = Number(arg.slice('--port='.length));
    } else if (!arg.startsWith('-')) {
      options.command = arg;
    }
  }

  return options;
}

function toServeOptions(options: CliOptions) {
  return {
    content: options.content,
    output: options.output,
    templates: options.templates,
    port: options.port,
  };
}

export function run(argv: string[]): BuildResult | Promise<ServeHandle> {
  const options = parseArgs(argv);
  if (options.command === 'serve') {
    return startServer(toServeOptions(options));
  }
  if (options.command !== 'build') {
    throw new Error('Unknown command. Usage: ssg build|serve [--content <dir>] [--output <dir>]');
  }
  return buildSite({
    contentDir: options.content || './content',
    outputDir: options.output || './dist',
    templatesDir: options.templates,
  });
}

export function main(argv: string[] = process.argv): void {
  const options = parseArgs(argv);
  if (options.command === 'serve') {
    startServer(toServeOptions(options))
      .then((handle) => {
        console.log(`Dev server listening on ${handle.address}`);
        console.log(`Watching ${options.content || './content'} and ${options.templates || './templates'}`);
        console.log(`Serving ${options.output || './dist'}`);
      })
      .catch((err) => {
        console.error(`Failed to start dev server: ${err.message}`);
        process.exitCode = 1;
      });
    return;
  }
  if (options.command !== 'build') {
    console.error('Usage: ssg build|serve [--content <dir>] [--output <dir>] [--port <n>]');
    process.exitCode = 1;
    return;
  }
  const result = buildSite({
    contentDir: options.content || './content',
    outputDir: options.output || './dist',
    templatesDir: options.templates,
  });
  console.log(`Built ${result.posts.length} page(s) into ${options.output || './dist'}`);
}

if (require.main === module) {
  main();
}

